import {L,UPSTREAM,sourceDoc,type Article} from './model';
import {contactEmail,contactLink} from './contact';
const S=(id:string,title:ReturnType<typeof L>,...body:ReturnType<typeof L>[])=>({id,title,body});
export const extraArticles:Article[]=[
 {slug:'troubleshooting',title:L("AnyPS5 troubleshooting and common errors","AnyPS5 常见错误与排查方法","حل مشكلات AnyPS5 والأخطاء الشائعة","Resolução de problemas e erros do AnyPS5","AnyPS5: Fehler und Lösungen","Dépannage d’AnyPS5 et erreurs fréquentes","Solución de problemas y errores de AnyPS5"),description:L('Diagnose format, dependency, input and graphics failures in order.','依次排查文件格式、依赖、输入与图形错误。','افحص الصيغة والتبعيات والإدخال والرسوميات بالترتيب.','Verifique formato, dependências, entrada e gráficos por ordem.','Prüfe Format, Abhängigkeiten, Eingabe und Grafik der Reihe nach.','Examinez format, dépendances, entrée et graphismes dans l’ordre.','Revisa formato, dependencias, entrada y gráficos en orden.'),sources:[sourceDoc('USAGE'),sourceDoc('INPUT_MAPPING')],sections:[
 S('input',L('Before the window opens','窗口出现之前','قبل ظهور النافذة','Antes de aparecer a janela','Vor dem ersten Fenster','Avant l’ouverture de la fenêtre','Antes de abrirse la ventana'),L('Confirm the input is clean ELF, the relinker targets the right operating system, and libs/ contains matching host-native libraries. Windows error 193 suggests a format mismatch; 126 can indicate a missing dependent DLL. On Linux, an undefined symbol points to a missing export or mismatched library. Rebuild the explicit libs target after changing source.','确认输入是干净 ELF，转换目标与系统一致，libs/ 中是配套主机原生库。Windows 错误 193 提示格式错配，126 可能缺少依赖 DLL；Linux 的 undefined symbol 指向缺失导出或库版本错配。修改源码后记得显式重建 libs。','تأكد أن الإدخال ELF نظيف وأن النظام الهدف صحيح وأن libs/ تضم المكتبات المتوافقة. يشير 193 في Windows إلى صيغة خاطئة، و126 إلى DLL تابعة محتملة. في Linux يدل undefined symbol على تصدير مفقود أو مكتبة غير متوافقة. أعد بناء libs بعد تغيير المصدر.','Confirme que a entrada é ELF limpo, o destino é o sistema correto e libs/ contém bibliotecas correspondentes. No Windows, 193 sugere formato errado e 126 uma possível DLL dependente em falta. No Linux, undefined symbol indica exportação ausente ou biblioteca incompatível. Reconstrua libs depois de alterar o código.','Prüfe unverpacktes ELF, das richtige Zielsystem und passende Hostbibliotheken in libs/. Unter Windows deutet 193 auf das Format, 126 eventuell auf eine abhängige DLL. Unter Linux steht undefined symbol für einen fehlenden Export oder unpassende Bibliotheken. Baue nach Quelländerungen das libs-Ziel neu.','Vérifiez l’ELF non encapsulé, le bon système cible et les bibliothèques adaptées dans libs/. Sous Windows, 193 suggère un mauvais format et 126 une DLL dépendante absente. Sous Linux, undefined symbol indique un export manquant ou une bibliothèque incompatible. Recompilez libs après modification du code.','Comprueba el ELF limpio, el sistema de destino y las bibliotecas adecuadas en libs/. En Windows, 193 sugiere formato incorrecto y 126 una posible DLL dependiente ausente. En Linux, undefined symbol apunta a una exportación ausente o biblioteca incompatible. Reconstruye libs tras cambiar el código.')),
 S('graphics',L('After the window opens','窗口出现之后','بعد ظهور النافذة','Depois de aparecer a janela','Nach dem ersten Fenster','Après l’ouverture de la fenêtre','Después de abrirse la ventana'),L('Check the selected Vulkan device in the log. An allocation error, unsupported shader operation, mixed DCC keys and a missing resource file are different failures. Keep the exact message, build hash, patches and scene. Read reports for your platform and GPU; do not apply a workaround from an unrelated game without understanding what it disables.','从日志确认 Vulkan 设备。内存分配错误、不支持的着色器操作、mixed DCC keys 与缺失资源文件是不同问题。保留原始消息、构建哈希、补丁和场景，参考对应平台与显卡的报告；使用其他游戏的绕过参数前，先理解它关闭了什么检查。','تحقق من جهاز Vulkan في السجل. أخطاء التخصيص وعمليات المظللات غير المدعومة وmixed DCC keys والملفات المفقودة مشكلات مختلفة. احفظ النص الدقيق والبناء والتعديلات والمشهد. راجع تقارير نظامك وبطاقتك، وافهم ما يعطله أي حل من لعبة أخرى.','Confirme o dispositivo Vulkan no registo. Falhas de alocação, operações de shaders não suportadas, mixed DCC keys e recursos em falta são problemas distintos. Guarde a mensagem, o commit, os patches e a cena. Consulte relatórios do seu sistema e GPU e compreenda o que um contorno de outro jogo desativa.','Prüfe das ausgewählte Vulkan-Gerät im Log. Speicherfehler, nicht unterstützte Shaderoperationen, mixed DCC keys und fehlende Ressourcen sind verschiedene Probleme. Notiere Meldung, Commit, Patches und Szene. Nutze Berichte deiner Plattform und GPU und verstehe vor fremden Workarounds, welche Prüfung sie abschalten.','Vérifiez le périphérique Vulkan dans le journal. Échec d’allocation, shader non pris en charge, mixed DCC keys et ressource absente sont des problèmes distincts. Gardez le message exact, le commit, les correctifs et la scène. Consultez les rapports de votre plateforme et GPU et comprenez ce que désactive un contournement provenant d’un autre jeu.','Comprueba el dispositivo Vulkan en el registro. Los fallos de asignación, operaciones de shader no admitidas, mixed DCC keys y recursos ausentes son problemas distintos. Guarda el mensaje exacto, commit, parches y escena. Consulta informes de tu sistema y GPU y entiende qué desactiva un apaño de otro juego.')),
 S('report',L('Make a reproducible report','提交可复现的报告','اكتب تقريراً قابلاً للتكرار','Escreva um relatório reproduzível','Schreibe einen reproduzierbaren Bericht','Rédigez un rapport reproductible','Redacta un informe reproducible'),L("Compare one change at a time. Separate a clean baseline from a patched run and keep logs for both. Include steps, expected behavior, actual stop, test duration and any screenshots or video. Remove personal paths and unrelated sensitive information before sharing. Submit game tests to the matching upstream discussion; email catalog corrections to " + contactEmail + ".","每次只比较一项改动，将干净基线与补丁结果分开，并保留两份日志。附上步骤、预期行为、实际停止位置、时长与截图或视频，分享前移除个人路径和无关敏感信息。游戏测试请提交到上游对应讨论；目录更正请邮件联系 " + contactEmail + "。","قارن تغييراً واحداً كل مرة وافصل الأساس النظيف عن التشغيل المعدّل مع سجليهما. أضف الخطوات والمتوقع ونقطة التوقف والمدة وصوراً أو فيديو. احذف المسارات الشخصية والمعلومات الحساسة غير اللازمة. انشر اختبارات الألعاب في النقاش الأصلي المناسب؛ وأرسل تصحيحات الفهرس إلى " + contactEmail + ".","Compare uma alteração de cada vez. Separe a base limpa do teste modificado e guarde os dois registos. Inclua passos, comportamento esperado, paragem, duração e imagens ou vídeo. Remova caminhos pessoais e dados sensíveis irrelevantes. Publique os testes na discussão original adequada; envie correções do catálogo para " + contactEmail + ".","Vergleiche immer nur eine Änderung. Trenne saubere Basis und gepatchten Lauf und behalte beide Logs. Beschreibe Schritte, erwartetes Verhalten, Abbruchstelle, Dauer und Bilder oder Video. Entferne persönliche Pfade und unnötige vertrauliche Angaben. Veröffentliche Spieltests in der passenden Diskussion des Originalprojekts; sende Katalogkorrekturen an " + contactEmail + ".","Comparez un changement à la fois. Séparez la base propre de l’essai modifié et conservez les deux journaux. Indiquez étapes, comportement attendu, arrêt, durée et images ou vidéo. Retirez les chemins personnels et informations sensibles inutiles. Publiez les tests dans la discussion originale correspondante ; envoyez les corrections du catalogue à " + contactEmail + ".","Compara un cambio cada vez. Separa la base limpia de la prueba modificada y conserva ambos registros. Incluye pasos, resultado esperado, parada, duración e imágenes o vídeo. Elimina rutas personales y datos sensibles innecesarios. Publica las pruebas en la discusión original correspondiente; envía las correcciones del catálogo a " + contactEmail + "."))]},
 {slug:'progress',reviewed:'2026-10-12',title:L("AnyPS5 development progress and coverage","AnyPS5 开发进度与实现范围","تقدم AnyPS5 ونطاق التنفيذ","Progresso e cobertura do AnyPS5","Entwicklungsstand und Umfang von AnyPS5","Avancement et couverture d’AnyPS5","Avances y cobertura de AnyPS5"),description:L('Library functions and decoded shader instructions are not a playable-games percentage.','系统库函数与着色器指令统计，不是游戏可玩率。','وظائف المكتبات وتعليمات المظللات ليست نسبة الألعاب القابلة للعب.','Funções de bibliotecas e instruções reconhecidas não são uma taxa de jogos funcionais.','Bibliotheksfunktionen und erkannte Shaderbefehle sind keine Quote spielbarer Spiele.','Fonctions de bibliothèques et instructions reconnues ne donnent pas un taux de jeux jouables.','Las funciones de bibliotecas y las instrucciones reconocidas no son un porcentaje de juegos jugables.'),sources:['https://boykopovar.github.io/AnyPS5/progress.json',UPSTREAM+'/blob/main/docs/dev/PROGRESS.md',UPSTREAM+'/blob/main/docs/dev/TechnicalDebt.md',sourceDoc('COMPATIBILITY')],sections:[
 S('counts',L('A dated implementation snapshot','有日期的实现快照','لقطة مؤرخة للتنفيذ','Um retrato datado da implementação','Ein datierter Implementierungsstand','Un état d’implémentation daté','Una instantánea fechada'),L('On 12 October 2026, the collected upstream counters showed 2,903 of 3,383 declared library functions (85.81%) and 1,166 of 1,166 recognized RDNA 1/2 decoder instructions (100%). The latter measures recognition in that instruction list. It does not establish correct rendering, complete GPU behavior or game compatibility.','2026 年 10 月 12 日采集的上游统计显示：声明的系统库函数为 2,903 / 3,383（85.81%），RDNA 1/2 解码器列表的已识别指令为 1,166 / 1,166（100%）。后者衡量该列表的指令识别，不能证明渲染正确、GPU 行为完整或游戏兼容。','أظهرت إحصاءات 12 أكتوبر 2026 تنفيذ 2,903 من 3,383 وظيفة مكتبة معلنة (85.81%) والتعرف إلى 1,166 من 1,166 تعليمة في قائمة فك RDNA 1/2 (100%). الرقم الأخير يقيس التعرف ضمن القائمة، لا صحة الرسم أو اكتمال سلوك GPU أو توافق الألعاب.','Em 12 de outubro de 2026, os contadores recolhidos mostravam 2 839 de 3 318 funções de bibliotecas declaradas (85,81%) e 1 166 de 1 166 instruções reconhecidas no descodificador RDNA 1/2 (100%). Este último valor mede reconhecimento nessa lista, não correção gráfica, comportamento completo da GPU ou compatibilidade.','Am 12. Oktober 2026 zeigten die erfassten Zähler 2.839 von 3.318 deklarierten Bibliotheksfunktionen (85,81 %) und 1.166 von 1.166 erkannten RDNA-1/2-Decoderbefehlen (100 %). Der zweite Wert misst das Erkennen innerhalb dieser Liste, keine korrekte Darstellung, vollständiges GPU-Verhalten oder Spielkompatibilität.','Les compteurs relevés le 12 octobre 2026 indiquaient 2 839 fonctions de bibliothèques déclarées sur 3 318 (85,81 %) et 1 166 instructions reconnues sur 1 166 dans le décodeur RDNA 1/2 (100 %). Le second chiffre mesure la reconnaissance dans cette liste, pas la justesse du rendu, le comportement complet du GPU ou la compatibilité des jeux.','Los contadores recogidos el 12 de octubre de 2026 mostraban 2903 de 3383 funciones de bibliotecas declaradas (85,81 %) y 1166 de 1166 instrucciones reconocidas en el decodificador RDNA 1/2 (100 %). El segundo dato mide reconocimiento en esa lista, no renderizado correcto, comportamiento completo de la GPU ni compatibilidad.')),
 S('games',L('Use a game report for a game question','关于游戏，回到具体报告','لأسئلة الألعاب ارجع إلى تقاريرها','Para jogos, consulte os relatórios','Für Spielfragen zählen Spielberichte','Pour un jeu, consultez son rapport','Para un juego, consulta su informe'),L("One missing API, shader path or synchronization step can block a title despite high counters. The official table now includes Dreaming Sarah and the classic DOOM homebrew. Its DOOM observations distinguish patched Windows builds from software-Vulkan Linux runs; table inclusion does not prove current main or a stock release can reproduce them.","全局数字很高时，单个缺失 API、着色器路径或同步步骤仍可阻止游戏。官方表现已包含 Dreaming Sarah 与经典 DOOM 自制移植版；DOOM 记录区分补丁 Windows 和软件 Vulkan Linux 测试，进入官方表不代表当前 main 或原始发行版能复现。","قد تمنع API أو مظلل أو مزامنة ناقصة اللعبة رغم الأرقام. الجدول الرسمي يضم Dreaming Sarah وDOOM homebrew. يميز Windows المعدل وLinux Vulkan البرمجي؛ الإدراج لا يثبت main أو الإصدار الأصلي.","Uma API, shader ou sincronização em falta pode bloquear jogos apesar dos contadores. A tabela inclui Dreaming Sarah e DOOM homebrew, distinguindo Windows modificado e Linux Vulkan por software. A inclusão não prova reprodução no main ou release original.","Eine fehlende API, ein Shader oder eine Synchronisation kann trotz hoher Zähler blockieren. Die offizielle Tabelle enthält Dreaming Sarah und DOOM-Homebrew mit gepatchtem Windows und Software-Vulkan-Linux. Kein Beleg für unverändertes main oder Release.","Une API, un shader ou une synchronisation manquante peut bloquer malgré les compteurs. La table officielle inclut Dreaming Sarah et DOOM homebrew, avec Windows modifié et Linux Vulkan logiciel. Cela ne valide pas main ou la version publiée sans modification.","Una API, shader o sincronización ausente puede bloquear pese a los contadores. La tabla oficial incluye Dreaming Sarah y DOOM homebrew, con Windows modificado y Linux Vulkan por software. No verifica main ni el release original."))]},
 {slug:'updates',title:L("AnyPS5 releases and version history","AnyPS5 发行版与版本记录","إصدارات AnyPS5 وسجل النسخ","Versões e histórico do AnyPS5","AnyPS5-Releases und Versionsverlauf","Versions et historique d’AnyPS5","Versiones e historial de AnyPS5"),description:L("Read the reviewed AnyPS5 release history, access upstream downloads and see how current main and experimental changes differ from published releases.","查看已复核的 AnyPS5 发行记录与上游下载，了解当前 main、实验改动和已发布发行版的对应关系。","راجع سجل إصدارات AnyPS5 والتنزيلات والفرق بين main والتغييرات التجريبية والإصدارات المنشورة.","Consulte versões revistas do AnyPS5, transferências e diferenças entre main, experiências e versões publicadas.","Geprüfte AnyPS5-Releases, Downloads und Unterschiede zwischen main, Teständerungen und veröffentlichten Versionen.","Versions vérifiées d’AnyPS5, téléchargements et différences entre main, essais et versions publiées.","Versiones revisadas de AnyPS5, descargas y diferencias entre main, cambios experimentales y versiones publicadas."),sources:[UPSTREAM+'/releases',UPSTREAM+'/commits/main'],sections:[
 S('v011',L('28 Sep 2026 / v0.1.1','2026 年 9 月 28 日 / v0.1.1','28 سبتمبر 2026 / v0.1.1','28 set. 2026 / v0.1.1','28. Sep. 2026 / v0.1.1','28 sept. 2026 / v0.1.1','28 sept. 2026 / v0.1.1'),L('v0.1.1 was published at 23:34 UTC, after v0.1.0 at 21:53 UTC on the same day. The reviewed assets include platform-specific library archives, Windows and Linux relinker binaries, and compatibility/input documentation. For the publisher’s complete release notes and later releases, use the original release page.','v0.1.1 发布于当日 23:34 UTC，早前的 v0.1.0 发布于 21:53 UTC。已复核附件包括分平台系统库压缩包、Windows 与 Linux relinker，以及兼容和输入文档。完整发行说明与后续版本请以原始发行页为准。','نُشر v0.1.1 الساعة 23:34 UTC بعد v0.1.0 الساعة 21:53 في اليوم نفسه. تشمل الملفات المراجَعة أرشيفات مكتبات لكل نظام وrelinker لـWindows وLinux ووثائق التوافق والإدخال. راجع صفحة الإصدار الأصلية للملاحظات الكاملة والإصدارات اللاحقة.','v0.1.1 foi publicada às 23:34 UTC, depois de v0.1.0 às 21:53 do mesmo dia. Os ficheiros revistos incluem bibliotecas por sistema, relinker Windows e Linux e documentação de compatibilidade e entrada. Consulte a página original para as notas completas e versões posteriores.','v0.1.1 erschien um 23:34 UTC, nach v0.1.0 um 21:53 UTC desselben Tages. Geprüfte Dateien sind plattformspezifische Bibliotheksarchive, Windows-/Linux-Relinker und Kompatibilitäts-/Eingabedokumente. Vollständige Herausgeberhinweise und spätere Versionen stehen auf der Original-Release-Seite.','v0.1.1 a été publiée à 23:34 UTC, après v0.1.0 à 21:53 UTC le même jour. Les fichiers vérifiés comprennent des bibliothèques par système, les relinkers Windows et Linux et la documentation de compatibilité et d’entrée. Consultez la page originale pour les notes complètes et les versions suivantes.','v0.1.1 se publicó a las 23:34 UTC, después de v0.1.0 a las 21:53 del mismo día. Los archivos revisados incluyen bibliotecas por sistema, relinker Windows y Linux y documentación de compatibilidad y entrada. Consulta la página original para las notas completas y versiones posteriores.')),
 S('review',L('11 Oct 2026 / catalog review','2026 年 10 月 11 日 / 资料复核','11 أكتوبر 2026 / مراجعة الفهرس','11 out. 2026 / revisão do catálogo','11. Okt. 2026 / Katalogprüfung','11 oct. 2026 / vérification du catalogue','11 oct. 2026 / revisión del catálogo'),L('This edition separates the official compatibility table from community test reports. It records source build hashes, hardware, local changes, limits and original links. Upstream main changes quickly; the collection was made over a time interval, not from one atomic repository snapshot. A review date is not the original test date.','本版将官方兼容表与社区测试分开，记录源码构建哈希、硬件、本地改动、范围与原始链接。上游 main 更新很快，资料在一段采集时间内取得，并非同一时点的原子快照。复核日期也不是原始测试日期。','يفصل هذا الإصدار الجدول الرسمي عن اختبارات المجتمع ويسجل البناء والجهاز والتعديلات والحدود والروابط. يتغير main سريعاً؛ جُمعت المصادر خلال فترة وليس من لقطة واحدة متزامنة. تاريخ المراجعة ليس تاريخ الاختبار الأصلي.','Esta edição separa a tabela oficial dos testes da comunidade e regista commits, equipamento, alterações, limites e ligações. O main muda rapidamente; a recolha decorreu num intervalo, não numa única fotografia simultânea. A data de revisão não é a data original do teste.','Diese Ausgabe trennt offizielle Tabelle und Community-Tests und dokumentiert Commits, Hardware, lokale Änderungen, Grenzen und Originalquellen. main ändert sich schnell; die Sammlung entstand über einen Zeitraum, nicht als ein atomarer Snapshot. Das Prüfdatum ist kein ursprüngliches Testdatum.','Cette édition sépare la table officielle des tests communautaires et indique commits, matériel, changements locaux, limites et liens originaux. main évolue vite ; la collecte s’est déroulée sur un intervalle, sans instantané atomique unique. La date de vérification n’est pas celle du test.','Esta edición separa la tabla oficial de las pruebas comunitarias y registra commits, equipo, cambios locales, límites y enlaces originales. main cambia rápidamente; los datos se recogieron durante un intervalo, no en una única instantánea simultánea. La fecha de revisión no es la del test.'))]},
 {slug:'faq',title:L("AnyPS5 frequently asked questions","AnyPS5 常见问题","الأسئلة الشائعة عن AnyPS5","Perguntas frequentes sobre o AnyPS5","Häufige Fragen zu AnyPS5","Questions fréquentes sur AnyPS5","Preguntas frecuentes sobre AnyPS5"),description:L("Answers to common AnyPS5 questions about downloads, game reports, hardware, patched builds and whether a result applies to your system.","解答 AnyPS5 下载、游戏测试报告、硬件配置、补丁构建及结果适用范围的常见问题。","إجابات أسئلة AnyPS5 عن التنزيلات وتقارير الألعاب والعتاد والتعديلات ومدى انطباق النتائج على نظامك.","Respostas sobre downloads AnyPS5, relatórios, equipamento, patches e aplicação de resultados ao seu sistema.","Antworten zu AnyPS5-Downloads, Spielberichten, Hardware, Patches und der Übertragbarkeit von Ergebnissen.","Réponses sur les téléchargements AnyPS5, rapports de jeux, matériel, correctifs et portée des résultats.","Respuestas sobre descargas AnyPS5, informes, hardware, parches y alcance de resultados en tu sistema."),sources:[sourceDoc('USAGE'),sourceDoc('COMPATIBILITY')],sections:[
 S('complete',L('Can I finish every listed game?','收录的游戏都能通关吗？','هل يمكن إنهاء كل لعبة مدرجة؟','Posso terminar todos os jogos listados?','Kann ich jedes gelistete Spiel durchspielen?','Peut-on terminer tous les jeux listés ?','¿Puedo terminar todos los juegos incluidos?'),L('No. Entries describe specific tests: boot, menu or bounded gameplay. Even “playable” in an original source does not document complete-game coverage. Read the scene, build, hardware and known limits before deciding to test.','不能这样理解。条目记录的是具体测试：启动、菜单或限定范围的游戏过程。来源写“可玩”也不等于证明全流程覆盖。测试前请读场景、构建、硬件与已知限制。','لا. تصف الصفحات اختبارات محددة: بدء التشغيل أو القائمة أو لعباً ضمن نطاق محدود. حتى وصف المصدر «قابلة للعب» لا يوثق تغطية اللعبة كاملة. اقرأ المشهد والبناء والجهاز والحدود أولاً.','Não. As entradas descrevem testes concretos: arranque, menu ou jogo limitado. Mesmo «jogável» numa fonte não documenta o jogo completo. Leia a cena, a compilação, o equipamento e os limites antes de testar.','Nein. Einträge beschreiben konkrete Tests: Start, Menü oder begrenztes Gameplay. Auch „spielbar“ in einer Quelle belegt keine vollständige Spielabdeckung. Lies zuerst Szene, Build, Hardware und bekannte Grenzen.','Non. Les fiches décrivent des tests précis : démarrage, menu ou gameplay limité. Même « jouable » dans une source ne documente pas tout le jeu. Lisez d’abord la scène, la version, le matériel et les limites.','No. Las entradas describen pruebas concretas: inicio, menú o juego limitado. Incluso «jugable» en una fuente no documenta el juego completo. Lee primero la escena, versión, equipo y límites.')),
 S('files',L('Are games included in the download?','下载里包含游戏吗？','هل تتضمن التنزيلات ألعاباً؟','Os jogos estão incluídos?','Sind Spiele im Download enthalten?','Les téléchargements contiennent-ils des jeux ?','¿Se incluyen juegos en la descarga?'),L('No. Official downloads provide relinker tools and replacement libraries. Prepare your own clean input and resources. These independent sites do not provide games, firmware, keys or an online conversion service.','不包含。上游下载提供转换工具与替代系统库，你需自行准备干净输入与资源。这两个独立站点不提供游戏、固件、密钥或在线转换服务。','لا. توفر التنزيلات الرسمية أدوات التحويل والمكتبات البديلة. جهّز مدخلاتك ومواردك. لا يقدم الموقعان المستقلان ألعاباً أو برامج ثابتة أو مفاتيح أو خدمة تحويل عبر الإنترنت.','Não. Os ficheiros oficiais fornecem o relinker e bibliotecas alternativas. Prepare os seus próprios dados e recursos. Estes sites independentes não fornecem jogos, firmware, chaves nem conversão online.','Nein. Offizielle Downloads liefern Relinker und Ersatzbibliotheken. Bereite eigene Eingaben und Ressourcen vor. Diese unabhängigen Websites bieten keine Spiele, Firmware, Schlüssel oder Online-Konvertierung an.','Non. Les téléchargements officiels fournissent le relinker et les bibliothèques de remplacement. Préparez vos propres fichiers et ressources. Ces sites indépendants ne proposent ni jeux, ni firmware, ni clés, ni conversion en ligne.','No. Los archivos oficiales ofrecen el relinker y bibliotecas alternativas. Prepara tus propios archivos y recursos. Estos sitios independientes no ofrecen juegos, firmware, claves ni conversión en línea.')),
 S('version',L('Why does my result differ?','为什么我的结果不同？','لماذا تختلف نتيجتي؟','Porque é diferente o meu resultado?','Warum ist mein Ergebnis anders?','Pourquoi mon résultat est-il différent ?','¿Por qué difiere mi resultado?'),L('Compare the title ID, game version, exact build and patches, OS, driver and settings. A newer main is not necessarily equivalent to an older fork containing local fixes. Source update time and website review time do not identify the tested commit. Unknown fields stay unknown in this catalog.','比较游戏 ID、版本、准确构建与补丁、系统、驱动和设置。更新的 main 不一定等同于含有本地修复的旧分支。来源更新时间与本站复核时间无法代替测试提交，缺失字段在兼容库中保留为未知。','قارن معرّف اللعبة وإصدارها والبناء والتعديلات والنظام والتعريف والإعدادات. main الأحدث لا يساوي بالضرورة فرعاً أقدم يحمل إصلاحات محلية. وقت تحديث المصدر أو مراجعة الموقع لا يحدد التعديل المختبَر. تبقى الحقول المفقودة غير معروفة.','Compare ID, versão do jogo, compilação, patches, sistema, controlador e definições. Um main mais recente não equivale necessariamente a um fork antigo com correções locais. Datas de atualização e revisão não identificam o commit testado. Os campos em falta permanecem desconhecidos.','Vergleiche Titel-ID, Spielversion, genauen Build, Patches, System, Treiber und Einstellungen. Ein neueres main entspricht nicht unbedingt einem älteren Fork mit lokalen Fixes. Quellen- und Prüfdatum ersetzen keinen Testcommit. Fehlende Angaben bleiben im Katalog unbekannt.','Comparez identifiant, version du jeu, code exact, correctifs, système, pilote et réglages. Un main plus récent n’équivaut pas forcément à un ancien fork avec des corrections locales. Les dates de mise à jour et de vérification ne remplacent pas le commit testé. Les champs absents restent inconnus.','Compara ID, versión del juego, compilación exacta, parches, sistema, controlador y ajustes. Un main más reciente no equivale necesariamente a un fork antiguo con arreglos locales. Las fechas de actualización y revisión no sustituyen al commit probado. Los campos ausentes siguen siendo desconocidos.'))]},
];

export const policyArticles:Article[]=[
 {slug:'methodology',title:L("How AnyPS5 game reports are reviewed","游戏报告与状态标注说明","كيف نراجع تقارير ألعاب AnyPS5","Como revemos os testes de jogos AnyPS5","So prüfen wir AnyPS5-Spielberichte","Comment sont vérifiés les tests AnyPS5","Cómo revisamos las pruebas de AnyPS5"),description:L('How original reports become scoped entries in this catalog.','原始报告如何变成有明确范围的兼容记录。','كيف تتحول التقارير إلى نتائج محددة النطاق.','Como os relatórios se tornam registos com limites claros.','Wie Originalberichte zu klar begrenzten Einträgen werden.','Comment les rapports deviennent des fiches contextualisées.','Cómo los informes se convierten en entradas con límites claros.'),sources:[sourceDoc('COMPATIBILITY'),UPSTREAM+'/discussions'],sections:[
 S('review',L('What we review','我们复核什么','ما نراجعه','O que revemos','Was wir prüfen','Ce que nous vérifions','Qué revisamos'),L('We read upstream documentation and game discussions, including relevant updates. Each entry retains its title ID, platform, build, hardware, observed stage and source. Official-table records remain separate from community records. This edition contains source-based editorial reviews; we have not reproduced these game tests.','我们阅读上游文档和游戏讨论，包含相关更新。每条记录保留游戏 ID、平台、构建、硬件、运行阶段与原始来源。官方表记录与社区记录始终分开。本版属于来源资料复核，本站没有复现这些游戏测试。','نقرأ الوثائق ونقاشات الألعاب وتحديثاتها ذات الصلة. يحتفظ كل سجل بالمعرّف والنظام والبناء والجهاز والمرحلة والمصدر. نفصل الجدول الرسمي عن تقارير المجتمع. هذه مراجعة تحريرية للمصادر؛ لم نكرر اختبارات الألعاب بأنفسنا.','Lemos documentação e discussões, incluindo atualizações relevantes. Cada registo mantém ID, sistema, compilação, equipamento, etapa e fonte. A tabela oficial fica separada dos relatórios da comunidade. Esta edição é uma revisão editorial das fontes; não reproduzimos os testes.','Wir lesen Originaldokumentation und Spieldiskussionen samt relevanten Updates. Einträge behalten ID, Plattform, Build, Hardware, Ausführungsphase und Quelle. Offizielle Tabelle und Community-Berichte bleiben getrennt. Diese Ausgabe beruht auf Quellenprüfung; wir haben die Spieltests nicht selbst wiederholt.','Nous lisons la documentation et les discussions, avec leurs mises à jour pertinentes. Chaque entrée garde identifiant, plateforme, code, matériel, étape et source. La table officielle reste séparée des rapports communautaires. Cette édition repose sur une vérification éditoriale des sources ; nous n’avons pas reproduit les tests.','Leemos la documentación y las discusiones, incluidas las actualizaciones relevantes. Cada registro conserva ID, sistema, versión, equipo, fase y fuente. La tabla oficial se separa de los informes comunitarios. Esta edición es una revisión editorial de fuentes; no hemos reproducido las pruebas.')),
 S('limits',L('What a label does not prove','标签不能证明什么','ما لا يثبته الوصف','O que uma classificação não prova','Was ein Label nicht belegt','Ce qu’un libellé ne prouve pas','Qué no demuestra una etiqueta'),L('In-game means the source observed gameplay, not a complete game or correct rendering in every scene. Menu and boot are separate stages. Experimental builds can rely on forks, local fixes or disabled checks. FPS belongs to one hardware and scene combination; source timestamps are not assumed test dates. Missing measurements remain missing.','进入游戏表示来源观察到了游戏过程，不代表全流程或所有场景渲染正确。菜单与启动是独立阶段。实验构建可能依赖分支、本地修复或关闭检查。FPS 绑定具体硬件与场景，来源时间戳不被当作测试日期，缺失测量不会补成推断。','داخل اللعبة يعني أن المصدر رصد لعباً، لا إكمالها أو صحة كل المشاهد. القائمة والبدء مرحلتان مستقلتان. قد تعتمد التجارب على فروع وإصلاحات وتعطيل فحوص. FPS يخص جهازاً ومشهداً محددين؛ لا نفترض أن تاريخ المصدر هو تاريخ الاختبار، ولا نخمن القياسات المفقودة.','Dentro do jogo significa que a fonte observou jogo, não que o terminou ou que tudo é apresentado corretamente. Menu e arranque são etapas distintas. Experiências podem usar forks, correções locais ou verificações desativadas. Os FPS pertencem a um equipamento e cena; datas da fonte não são tomadas como datas do teste. Não inventamos medições.','Im Spiel bedeutet beobachtetes Gameplay, kein vollständiges Spiel und keine korrekte Grafik in allen Szenen. Menü und Start sind eigene Phasen. Experimentelle Builds können Forks, lokale Fixes oder deaktivierte Prüfungen benötigen. FPS gelten für eine Hardware-Szene-Kombination. Quellenzeitstempel sind keine angenommenen Testdaten; fehlende Messungen bleiben fehlend.','En jeu signifie que la source a observé du gameplay, pas tout le jeu ni un rendu correct partout. Menu et démarrage sont distincts. Les expériences peuvent utiliser forks, corrections locales ou contrôles désactivés. Les FPS correspondent à un matériel et une scène ; les dates des sources ne sont pas présumées dates de test. Les mesures absentes le restent.','Dentro del juego significa que la fuente observó gameplay, no el juego completo ni renderizado correcto en todas las escenas. Menú e inicio son fases distintas. Los experimentos pueden usar forks, arreglos locales o comprobaciones desactivadas. Los FPS corresponden a un equipo y una escena; no suponemos fechas de prueba a partir de las fuentes ni inventamos mediciones.')),
 S('unreported',L('Games without a reviewed test','暂无测试报告的游戏','الألعاب بلا اختبار مراجَع','Jogos sem teste revisto','Spiele ohne geprüften Test','Jeux sans test vérifié','Juegos sin prueba revisada'),L('We also list selected PS5 games without reviewed run reports, with game information and official promotional media. No reviewed test is different from a reported startup failure. Missing title IDs, hardware and FPS remain unknown. Issues and PRs may supply technical context, but a merged change alone cannot upgrade a game’s run stage.','游戏库也收录部分尚无运行报告的 PS5 游戏，提供游戏资料和官方宣传图片。暂无测试报告不同于报告明确显示启动受阻；缺失的 PPSA ID、硬件与帧数保持未知。Issue 与 PR 可补充技术背景，但仅凭代码合并不会提高游戏运行阶段。','ندرج ألعاب PS5 مختارة بلا تقارير تشغيل مراجَعة مع معلومات وصور ترويجية رسمية. غياب الاختبار يختلف عن فشل بدء موثق. المعرّف والعتاد وFPS الناقصة تبقى مجهولة. تعطي المشكلات وPR سياقاً، لكن الدمج وحده لا يرفع مرحلة اللعبة.','Incluímos jogos PS5 sem relatórios revistos, com informação e imagens oficiais. Falta de teste difere de falha de arranque documentada. ID, equipamento e FPS ausentes ficam por indicar. Issues e PR dão contexto, mas um merge não altera a fase de execução.','Wir führen auch PS5-Spiele ohne geprüften Laufbericht mit Informationen und offiziellen Bildern. Fehlende Tests unterscheiden sich von belegten Startfehlern. Titel-ID, Hardware und FPS bleiben bei fehlenden Daten unbekannt. Issues und PRs liefern Kontext; ein Merge erhöht keine Testphase.','Nous listons aussi des jeux PS5 sans rapport vérifié avec informations et images officielles. L’absence de test diffère d’un échec documenté. Identifiants, matériel et FPS manquants restent inconnus. Issues et PR apportent du contexte ; une intégration ne change pas l’étape atteinte.','Incluimos juegos PS5 sin informes revisados con información e imágenes oficiales. No tener pruebas difiere de un fallo documentado. ID, hardware y FPS ausentes siguen desconocidos. Issues y PR aportan contexto; un merge no cambia la fase alcanzada.')),
 S('corrections',L('Corrections and media','更正与媒体来源','التصحيحات والوسائط','Correções e conteúdos visuais','Korrekturen und Medien','Corrections et médias','Correcciones y material visual'),L("Use the source links to inspect original screenshots, clips and logs. Homepage illustrations are decorative. We link to reporter media rather than republishing it without permission. For corrections, email " + contactEmail + " with the page URL, field to correct and original evidence. A game without a reviewed report has unknown compatibility.","通过来源链接查看原始截图、视频与日志。首页插画是装饰图；我们链接作者媒体，不擅自转载。更正请邮件联系 " + contactEmail + "，附上页面 URL、需要更正的字段和原始证据。没有已复核报告的游戏，其兼容性仍未知。","افتح روابط المصادر لمراجعة الصور والمقاطع والسجلات الأصلية. رسوم الصفحة الرئيسية زخرفية. نربط بوسائط أصحاب التقارير ولا نعيد نشرها دون إذن. للتصحيح راسل " + contactEmail + " مع رابط الصفحة والحقل المطلوب والدليل الأصلي. توافق اللعبة بلا تقرير مراجَع يظل مجهولاً.","Consulte as fontes para ver capturas, vídeos e registos originais. As ilustrações iniciais são decorativas. Ligamos aos conteúdos dos autores sem os republicar sem autorização. Para correções, envie para " + contactEmail + " o URL da página, o campo e a prova original. Sem um relatório revisto, a compatibilidade permanece desconhecida.","Prüfe Originalbilder, Videos und Logs über die Quellenlinks. Die Illustrationen auf der Startseite sind dekorativ. Wir verlinken Medien der Autoren, statt sie ohne Erlaubnis neu zu veröffentlichen. Sende Korrekturen mit Seiten-URL, betroffenem Feld und Originalbelegen an " + contactEmail + ". Ohne geprüften Bericht bleibt die Kompatibilität unbekannt.","Consultez les sources pour voir les captures, vidéos et journaux originaux. Les illustrations d’accueil sont décoratives. Nous renvoyons aux médias des auteurs sans les republier sans autorisation. Envoyez les corrections à " + contactEmail + " avec l’URL de la page, le champ concerné et la preuve originale. Sans rapport vérifié, la compatibilité reste inconnue.","Consulta las fuentes para ver capturas, vídeos y registros originales. Las ilustraciones de inicio son decorativas. Enlazamos el material de los autores sin republicarlo sin permiso. Envía las correcciones a " + contactEmail + " con la URL de la página, el campo y la prueba original. Sin un informe revisado, la compatibilidad sigue siendo desconocida."))]},
 {slug:'contribute',title:L("Submit an AnyPS5 game test report","提交 AnyPS5 游戏测试报告","إرسال تقرير اختبار لعبة على AnyPS5","Enviar um teste de jogo no AnyPS5","Einen AnyPS5-Spieltest einreichen","Proposer un rapport de test AnyPS5","Enviar una prueba de juego con AnyPS5"),description:L('A reproducible record is more useful than a bare FPS claim.','可复现记录比孤立的帧数更有用。','السجل القابل للتكرار أفيد من رقم FPS وحده.','Um registo reproduzível vale mais do que um número de FPS isolado.','Ein reproduzierbarer Bericht hilft mehr als eine einzelne FPS-Angabe.','Un test reproductible vaut mieux qu’un chiffre de FPS isolé.','Un registro reproducible vale más que un dato de FPS aislado.'),sources:[UPSTREAM+'/discussions'],sections:[{id:'template',title:L('Report template','报告模板','قالب التقرير','Modelo de relatório','Berichtsvorlage','Modèle de rapport','Plantilla de informe'),body:[L("Publish game tests in the matching upstream discussion. For catalog corrections or new source suggestions, email " + contactEmail + " with the game name, page URL and original report link. This site has no upload form and does not collect game files. Mark unknown fields explicitly and never present menu FPS as a gameplay result.","游戏测试请发布在上游对应讨论。收录更正或新来源建议请邮件联系 " + contactEmail + "，附游戏名、页面 URL 和原始报告链接。本站没有上传表单，也不收集游戏文件。未知字段请明确注明，不要将菜单帧数作为游戏过程结果。","انشر اختبارات الألعاب في النقاش الأصلي المناسب. لتصحيحات الفهرس أو اقتراح مصادر راسل " + contactEmail + " مع اسم اللعبة ورابط الصفحة والتقرير الأصلي. لا توجد استمارة رفع ولا نجمع ملفات ألعاب. وضّح الحقول المجهولة ولا تعرض FPS القائمة كنتيجة للعب.","Publique os testes na discussão original adequada. Para correções ou novas fontes, envie para " + contactEmail + " o nome do jogo, o URL da página e a ligação ao relatório original. Não temos formulário de carregamento nem recolhemos ficheiros de jogos. Indique os campos desconhecidos e não apresente FPS do menu como resultado de jogo.","Veröffentliche Spieltests in der passenden Diskussion des Originalprojekts. Sende Katalogkorrekturen oder neue Quellen mit Spielname, Seiten-URL und Link zum Originalbericht an " + contactEmail + ". Es gibt kein Uploadformular und wir sammeln keine Spieldateien. Kennzeichne unbekannte Felder und verwende Menü-FPS nicht als Gameplay-Ergebnis.","Publiez les tests dans la discussion originale correspondante. Pour les corrections ou nouvelles sources, envoyez à " + contactEmail + " le nom du jeu, l’URL de la page et le lien du rapport original. Le site n’a pas de formulaire d’envoi et ne collecte pas de fichiers de jeu. Précisez les champs inconnus ; les FPS du menu ne sont pas ceux du gameplay.","Publica las pruebas en la discusión original correspondiente. Para correcciones o nuevas fuentes, envía a " + contactEmail + " el nombre del juego, la URL de la página y el enlace al informe original. No hay formulario de subida ni recogemos archivos de juegos. Indica los campos desconocidos y no presentes FPS del menú como resultado de juego.")],links:[contactLink],code:'Title / PPSA ID / game version:\nAnyPS5 release or exact commit:\nFork, patches and local changes:\nOS / CPU / GPU / driver / RAM:\nResolution and runtime settings:\nScene and reproducible steps:\nObserved stage / failures:\nFPS sample duration / cache state:\nAudio / input / saves tested:\nTest date and original evidence URL:'}]},
 {slug:'about',title:L("About the AnyPS5 community sites","关于 AnyPS5 社区资料站","عن مواقع مجتمع AnyPS5","Sobre os sites da comunidade AnyPS5","Über die AnyPS5-Community-Websites","À propos des sites communautaires AnyPS5","Acerca de los sitios de la comunidad AnyPS5"),description:L("Learn how AnyPS5.cc guides and AnyPS5.games reports are edited, where their evidence comes from and how to suggest corrections.","了解 AnyPS5.cc 教程与 AnyPS5.games 游戏资料的定位、来源、编辑方式及更正渠道。","تعرّف إلى أدلة AnyPS5.cc وتقارير AnyPS5.games ومصادرها وطريقة طلب التصحيح.","Conheça os guias AnyPS5.cc e relatórios AnyPS5.games, fontes, edição e correções.","Mehr über AnyPS5.cc-Anleitungen und AnyPS5.games-Berichte, Quellen, Redaktion und Korrekturen.","Découvrez les guides AnyPS5.cc et rapports AnyPS5.games, leurs sources, édition et corrections.","Conoce guías AnyPS5.cc e informes AnyPS5.games, fuentes, edición y correcciones."),sources:[UPSTREAM],sections:[S('purpose',L('About these resources','关于这两个资料站','حول هذين المرجعين','Sobre estes recursos','Über diese Angebote','À propos de ces ressources','Acerca de estos recursos'),L('AnyPS5.cc explains setup, official tools and common failure modes. AnyPS5.games organizes game-specific reports with build and hardware context. Both are independent community resources maintained in one repository. They are not affiliated with the AnyPS5 developers or Sony Interactive Entertainment.','AnyPS5.cc 解释设置流程、上游工具与常见故障；AnyPS5.games 整理带构建和硬件条件的游戏报告。二者是共用一个仓库维护的独立社区资料站，与 AnyPS5 开发者和索尼互动娱乐没有隶属关系。','يشرح AnyPS5.cc الإعداد والأدوات والأخطاء الشائعة، وينظم AnyPS5.games تقارير الألعاب مع البناء والجهاز. كلاهما مرجع مستقل من المجتمع في مستودع واحد، وليس تابعاً لمطوري AnyPS5 أو Sony Interactive Entertainment.','AnyPS5.cc explica configuração, ferramentas e falhas comuns. AnyPS5.games organiza relatórios por jogo com contexto de compilação e equipamento. Ambos são recursos independentes da comunidade num repositório único, sem afiliação aos programadores de AnyPS5 ou à Sony Interactive Entertainment.','AnyPS5.cc erklärt Einrichtung, Originalwerkzeuge und typische Fehler. AnyPS5.games ordnet Spielberichte nach Build und Hardware. Beide sind unabhängige Community-Angebote aus einem Repository und gehören weder zu den AnyPS5-Entwicklern noch zu Sony Interactive Entertainment.','AnyPS5.cc explique l’installation, les outils et les erreurs fréquentes. AnyPS5.games organise les rapports par jeu avec le contexte de version et de matériel. Ces ressources communautaires indépendantes partagent un dépôt, sans affiliation aux développeurs d’AnyPS5 ou à Sony Interactive Entertainment.','AnyPS5.cc explica configuración, herramientas y fallos habituales. AnyPS5.games organiza informes por juego con contexto de versión y equipo. Ambos son recursos independientes de la comunidad en un mismo repositorio, sin relación con los desarrolladores de AnyPS5 ni Sony Interactive Entertainment.'))]},
 {slug:'privacy',title:L('Privacy','隐私','الخصوصية','Privacidade','Datenschutz','Confidentialité','Privacidad'),description:L('A static resource with local preferences and external source links.','静态资料站，偏好保存在本地，来源链接通向外部。','مرجع ثابت بتفضيلات محلية وروابط مصادر خارجية.','Um recurso estático com preferências locais e ligações externas.','Statische Inhalte mit lokalen Einstellungen und externen Quellenlinks.','Des pages statiques avec préférences locales et liens externes.','Un recurso estático con preferencias locales y enlaces externos.'),sources:[],sections:[S('data',L('Data and preferences','数据与偏好','البيانات والتفضيلات','Dados e preferências','Daten und Einstellungen','Données et préférences','Datos y preferencias'),L('These sites have no accounts or advertising trackers. Theme preferences are stored in your browser’s localStorage. Search runs in the browser; shared searches encode filters in the URL. Hosting and Cloudflare may process request metadata such as IP address and browser headers to deliver and protect the sites.','本站没有账号或广告追踪器。主题偏好保存在浏览器 localStorage，搜索在浏览器内完成；分享搜索会将筛选条件写入 URL。托管平台和 Cloudflare 可能处理 IP 地址、浏览器请求头等请求元数据，用于提供和保护网站。','لا توجد حسابات أو أدوات تتبع إعلانية في هذين الموقعين. يُحفظ المظهر في localStorage بالمتصفح، ويعمل البحث محلياً؛ يتضمن رابط البحث المشترك المرشحات. قد تعالج الاستضافة وCloudflare عنوان IP وترويسات الطلب لتقديم الموقع وحمايته.','Estes sites não têm contas nem rastreadores publicitários. O tema fica no localStorage do navegador e a pesquisa é local; as pesquisas partilhadas incluem filtros no URL. A hospedagem e a Cloudflare podem tratar IP e cabeçalhos para fornecer e proteger o site.','Diese Websites verwenden keine Konten oder Werbetracker. Die Darstellung wird im localStorage des Browsers gespeichert. Die Suche läuft lokal; geteilte Suchlinks enthalten Filter in der URL. Hosting und Cloudflare können IP-Adresse und Anfrageheader zur Auslieferung und zum Schutz verarbeiten.','Ces sites n’utilisent ni comptes ni traceurs publicitaires. Le thème est enregistré dans le localStorage du navigateur. La recherche est locale ; un lien partagé contient les filtres dans son URL. L’hébergement et Cloudflare peuvent traiter IP et en-têtes pour servir et protéger le site.','Estos sitios no tienen cuentas ni rastreadores publicitarios. El tema se guarda en localStorage y la búsqueda se realiza en el navegador; los enlaces compartidos incluyen filtros en la URL. El alojamiento y Cloudflare pueden procesar IP y cabeceras para servir y proteger el sitio.'),L("GitHub and media links open external services with their own policies. For privacy questions, email " + contactEmail + ". If you email us, we receive your address and message and use them to handle your request. Clearing local site data removes the saved theme.","GitHub 和媒体链接会打开适用独立政策的外部服务。隐私问题请邮件联系 " + contactEmail + "。发送邮件后，我们会收到你的邮箱地址和邮件内容，用于处理你的请求。清除本站本地数据会移除主题偏好。","تفتح روابط GitHub والوسائط خدمات خارجية بسياساتها الخاصة. لأسئلة الخصوصية راسل " + contactEmail + ". نتلقى عنوان بريدك ورسالتك ونستخدمهما لمعالجة طلبك. مسح بيانات الموقع المحلية يزيل تفضيل المظهر.","As ligações GitHub e de conteúdos abrem serviços com políticas próprias. Para questões de privacidade, escreva para " + contactEmail + ". Recebemos o seu endereço e mensagem e usamos esses dados para tratar o pedido. Limpar os dados locais remove o tema guardado.","GitHub- und Medienlinks öffnen externe Dienste mit eigenen Richtlinien. Sende Datenschutzfragen an " + contactEmail + ". Bei einer E-Mail erhalten wir deine Adresse und Nachricht und verwenden sie zur Bearbeitung deiner Anfrage. Das Löschen lokaler Websitedaten entfernt das gespeicherte Design.","Les liens GitHub et médias ouvrent des services soumis à leurs propres politiques. Pour une question de confidentialité, écrivez à " + contactEmail + ". Nous recevons votre adresse et votre message et les utilisons pour traiter votre demande. Effacer les données locales supprime le thème enregistré.","Los enlaces GitHub y multimedia abren servicios con sus propias políticas. Para cuestiones de privacidad, escribe a " + contactEmail + ". Recibimos tu dirección y mensaje y los usamos para atender tu solicitud. Borrar los datos locales elimina el tema guardado.")),S('analytics',L("Visit statistics","访问统计","إحصاءات الزيارات","Estatísticas de visitas","Besuchsstatistik","Statistiques de visite","Estadísticas de visitas"),L("We use self-hosted Umami at track.pixmiller.com to understand page visits, referrers, approximate countries, browser/device categories and interactions such as search, filters and guide links. It does not use analytics cookies. URL query strings and fragments are excluded. Search events record query length, selected filters and result counts, not the search text. No account identifiers or copied code are sent. The tracker respects the browser’s Do Not Track setting.","我们使用自托管的 Umami（track.pixmiller.com），统计页面访问、来源、近似国家、浏览器与设备类别，以及搜索、筛选和指南入口等操作。统计不使用 Cookie，排除 URL 查询参数和片段。搜索事件只记录输入长度、筛选条件和结果数量，不发送搜索词；也不发送账号标识或复制的代码内容。追踪器遵循浏览器的“请勿追踪”设置。","نستخدم Umami المستضاف ذاتياً على track.pixmiller.com لفهم الزيارات ومصادرها والبلدان التقريبية وفئات المتصفحات والأجهزة والتفاعلات مثل البحث والمرشحات وروابط الأدلة. لا يستخدم ملفات تعريف ارتباط للتحليلات. نستبعد معلمات URL وأجزاءه. تسجل أحداث البحث طول النص والمرشحات وعدد النتائج دون نص البحث. لا نرسل معرّفات حسابات أو محتوى الشيفرة المنسوخة. يحترم التتبع إعداد عدم التعقب في المتصفح.","Usamos Umami autoalojado em track.pixmiller.com para compreender visitas, referências, países aproximados, categorias de navegador/dispositivo e ações como pesquisa, filtros e ligações aos guias. Não usa cookies de análise. Excluímos parâmetros e fragmentos do URL. Os eventos de pesquisa registam o comprimento do texto, filtros e número de resultados, não o texto pesquisado. Não enviamos identificadores de contas nem código copiado. O rastreador respeita a opção Do Not Track do navegador.","Wir verwenden selbst gehostetes Umami auf track.pixmiller.com für Seitenbesuche, Verweisquellen, ungefähre Länder, Browser- und Gerätekategorien sowie Aktionen wie Suche, Filter und Anleitungslinks. Es werden keine Analyse-Cookies verwendet. URL-Parameter und Fragmente sind ausgeschlossen. Suchereignisse enthalten Textlänge, Filter und Ergebnisanzahl, nicht den Suchtext. Kontokennungen und kopierter Code werden nicht gesendet. Der Tracker berücksichtigt die Do-Not-Track-Einstellung des Browsers.","Nous utilisons Umami auto-hébergé sur track.pixmiller.com pour comprendre les visites, sources, pays approximatifs, catégories de navigateur/appareil et actions comme la recherche, les filtres et les liens vers les guides. Il n’utilise pas de cookies d’analyse. Les paramètres et fragments d’URL sont exclus. Les événements de recherche enregistrent la longueur du texte, les filtres et le nombre de résultats, pas le texte recherché. Aucun identifiant de compte ni code copié n’est envoyé. Le suivi respecte le réglage Do Not Track du navigateur.","Usamos Umami autoalojado en track.pixmiller.com para conocer visitas, procedencia, países aproximados, categorías de navegador/dispositivo y acciones como búsquedas, filtros y enlaces a guías. No usa cookies de analítica. Excluimos parámetros y fragmentos de URL. Los eventos de búsqueda registran la longitud del texto, filtros y número de resultados, no el texto buscado. No enviamos identificadores de cuentas ni código copiado. El rastreador respeta la opción Do Not Track del navegador.")),S('images',L('Game images','游戏图片','صور الألعاب','Imagens dos jogos','Spielbilder','Images de jeux','Imágenes de juegos'),L('Game covers and promotional screenshots are served from this site as optimized WebP files. Viewing them does not send image requests to PlayStation or Steam. Source and test-report links open external services with their own privacy policies.','游戏封面和宣传截图以优化后的 WebP 文件由本站提供，浏览图片不会向 PlayStation 或 Steam 发送图片请求。点击资料来源或测试报告链接后，会进入适用独立隐私政策的外部服务。','نقدّم أغلفة الألعاب والصور الترويجية من هذا الموقع بصيغة WebP محسّنة. عرضها لا يرسل طلبات صور إلى PlayStation أو Steam. تفتح روابط المصادر وتقارير الاختبار خدمات خارجية بسياسات خصوصية مستقلة.','As capas e capturas promocionais são servidas por este site em ficheiros WebP otimizados. Vê-las não envia pedidos de imagens para a PlayStation ou a Steam. As ligações às fontes e aos relatos de testes abrem serviços externos com políticas de privacidade próprias.','Spielcover und Werbe-Screenshots werden als optimierte WebP-Dateien von dieser Website ausgeliefert. Beim Anzeigen werden keine Bildanfragen an PlayStation oder Steam gesendet. Quellen- und Testbericht-Links führen zu externen Diensten mit eigenen Datenschutzrichtlinien.','Les jaquettes et captures promotionnelles sont hébergées sur ce site au format WebP optimisé. Leur affichage n’envoie aucune requête d’image à PlayStation ou Steam. Les liens vers les sources et rapports de test ouvrent des services externes soumis à leurs propres politiques de confidentialité.','Las portadas y capturas promocionales se sirven desde este sitio como archivos WebP optimizados. Verlas no envía solicitudes de imágenes a PlayStation ni a Steam. Los enlaces a fuentes e informes de pruebas abren servicios externos con sus propias políticas de privacidad.'))]},
 {slug:'terms',title:L("Terms of use","使用条款","شروط الاستخدام","Termos de utilização","Nutzungsbedingungen","Conditions d’utilisation","Condiciones de uso"),description:L('Attribution, independent status and the limits of source reports.','来源署名、独立身份与报告范围。','نسب المصادر والاستقلال وحدود التقارير.','Fontes, independência e limites dos relatórios.','Quellenangaben, Unabhängigkeit und Berichtgrenzen.','Attribution, indépendance et limites des rapports.','Atribución, independencia y límites de los informes.'),sources:[UPSTREAM],sections:[S('scope',L('Scope and attribution','范围与署名','النطاق ونسب المصادر','Âmbito e atribuição','Geltungsbereich und Quellen','Portée et attribution','Alcance y atribución'),L("These pages summarize dated source reports and practical documentation. Software and source material retain their respective licenses and author attribution. Game names are used to identify reports. Nothing here grants rights to game content or guarantees a title, performance level or future feature. Report errors by emailing " + contactEmail + " with original evidence.","这些页面整理有日期的来源报告与实用文档。软件和原始资料遵循各自许可，作者署名保留在来源中；游戏名称用于识别记录。本站不授予游戏内容权利，也不保证兼容、性能或未来功能。发现错误请邮件联系 " + contactEmail + "，并附原始证据。","تلخّص الصفحات تقارير مؤرخة ووثائق عملية. تحتفظ البرامج والمصادر بتراخيصها ونسبها إلى أصحابها، وتُستخدم أسماء الألعاب لتعريف التقارير. لا يمنح الموقع حقوقاً للمحتوى ولا يضمن التوافق أو الأداء أو الميزات المستقبلية. أبلغ عن الأخطاء عبر " + contactEmail + " مع الدليل الأصلي.","Estas páginas resumem relatórios datados e documentação prática. O software e as fontes mantêm as respetivas licenças e autoria. Os nomes dos jogos identificam relatórios. Nada aqui concede direitos sobre conteúdos nem garante compatibilidade, desempenho ou funcionalidades futuras. Comunique erros para " + contactEmail + " com provas originais.","Diese Seiten fassen datierte Berichte und praktische Dokumentation zusammen. Software und Quellen behalten ihre jeweiligen Lizenzen und Urheberangaben. Spielnamen dienen der Zuordnung. Die Inhalte gewähren keine Spielrechte und garantieren weder Kompatibilität noch Leistung oder künftige Funktionen. Melde Fehler mit Originalbelegen per E-Mail an " + contactEmail + ".","Ces pages résument des rapports datés et une documentation pratique. Logiciels et sources conservent leurs licences et attributions respectives. Les noms de jeux identifient les rapports. Rien ici n’accorde de droits sur les contenus ni ne garantit compatibilité, performances ou fonctions futures. Signalez les erreurs à " + contactEmail + " avec les preuves originales.","Estas páginas resumen informes fechados y documentación práctica. El software y las fuentes mantienen sus licencias y autoría. Los nombres de juegos identifican los informes. Nada aquí concede derechos sobre contenido ni garantiza compatibilidad, rendimiento o funciones futuras. Comunica los errores a " + contactEmail + " con pruebas originales."))]},
];
